using FlowOps.Core.Entities;
namespace FlowOps.Core.Interfaces;
public interface IGitHubService { Task<string> CommitDeploymentManifestAsync(string appName,string environment,string imageTag,int replicas,string commitMessage,CancellationToken ct=default); Task<string?> GetLatestCommitHashAsync(string branch="main",CancellationToken ct=default); Task<bool> IsRepositoryHealthyAsync(CancellationToken ct=default); }
public interface IArgoCDService { Task<List<ArgoAppStatus>> GetAllAppStatusesAsync(CancellationToken ct=default); Task<ArgoAppStatus?> GetAppStatusAsync(string appName,CancellationToken ct=default); Task<bool> ForceSyncAsync(string appName,CancellationToken ct=default); Task<bool> ForceSyncAllAsync(CancellationToken ct=default); }
public interface IKubernetesService { Task<List<Application>> GetRunningApplicationsAsync(CancellationToken ct=default); Task<List<Pod>> GetPodsAsync(string? appName=null,string? ns=null,CancellationToken ct=default); Task<List<ClusterInfo>> GetClustersAsync(CancellationToken ct=default); Task<ClusterInfo?> GetClusterAsync(string clusterName,CancellationToken ct=default); }
public interface IPrometheusService { Task<double> GetCurrentCpuUsageAsync(string? appName=null,CancellationToken ct=default); Task<double> GetCurrentMemoryUsageAsync(string? appName=null,CancellationToken ct=default); Task<double> GetRequestsPerSecondAsync(string? appName=null,CancellationToken ct=default); Task<MetricSeries> GetCpuTimeSeriesAsync(string? appName=null,int minutes=10,CancellationToken ct=default); Task<MetricSeries> GetMemoryTimeSeriesAsync(string? appName=null,int minutes=10,CancellationToken ct=default); Task<List<Alert>> GetActiveAlertsAsync(CancellationToken ct=default); }
public interface IDeploymentService { Task<Deployment> TriggerDeploymentAsync(string appName,string environment,string imageTag,int replicas,DeployStrategy strategy,string triggeredBy,CancellationToken ct=default); Task<List<Deployment>> GetDeploymentHistoryAsync(string? appName=null,string? environment=null,int take=50,CancellationToken ct=default); Task<Deployment?> GetDeploymentAsync(string deploymentId,CancellationToken ct=default); }
